//! The filter drawer lists all 24 keys before any track is loaded, so the wheel is written into
//! the bindings with the other generated types, from the same `Key` the tracks use.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    reason = "every function in this file is test code"
)]

use std::fs;
use std::path::PathBuf;

use resonance_api::track_key;
use resonance_core::key::Key;

#[test]
fn the_key_wheel_for_the_ui_is_written_from_core() {
    let mut text = String::from(
        "// This file is generated by `cargo test -p resonance-api` from `Key` in `crates/core`. \
         Do not edit this file manually.\n\nimport type { TrackKey } from './TrackKey';\n\n\
         export const KEY_WHEEL: TrackKey[] = [\n",
    );
    for key in Key::all() {
        let key = track_key(key);
        text.push_str(&format!(
            "  {{ camelot: \"{}\", open_key: \"{}\", name: \"{}\" }},\n",
            key.camelot, key.open_key, key.name
        ));
    }
    text.push_str("];\n");

    let folder = PathBuf::from(
        std::env::var("TS_RS_EXPORT_DIR").expect("cargo sets TS_RS_EXPORT_DIR for the bindings"),
    );
    let path = folder.join("KeyWheel.ts");
    if fs::read_to_string(&path).ok().as_deref() != Some(text.as_str()) {
        fs::write(&path, &text).unwrap();
    }
    assert_eq!(
        text.lines()
            .filter(|line| line.contains("camelot:"))
            .count(),
        24
    );
}
